import os, sys

ROOT = os.path.dirname(os.path.abspath(__file__))
apply = "--apply" in sys.argv

for numbered in sorted(os.listdir(ROOT)):
    numdir = os.path.join(ROOT, numbered)
    if not os.path.isdir(numdir):
        continue
    for name in sorted(os.listdir(numdir)):
        old_path = os.path.join(numdir, name)
        if not os.path.isdir(old_path):
            continue
        if " - " not in name:
            continue
        new_name = name.split(" - ", 1)[1].strip()
        if not new_name or new_name == name:
            continue
        new_path = os.path.join(numdir, new_name)
        if os.path.exists(new_path):
            print(f"SKIP (collision): {name} -> {new_name}")
            continue
        print(f"{'RENAME' if apply else 'WOULD RENAME'}: {numbered}/{name}  ->  {numbered}/{new_name}")
        if apply:
            os.rename(old_path, new_path)

print("\nDone." if apply else "\nDry run only. Re-run with --apply to actually rename.")

